        CONSTRAINT "PK_Budgets" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Budget_Amount" CHECK ("Amount" >= 0),
        CONSTRAINT "FK_Budgets_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Budgets_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE RESTRICT
